parameters.jsCode:
const response = $input.item.json;
const sourceData = $('2. Extract Record Data').first().json;
let raw = '';
try { raw = response.choices[0].message.content || ''; } catch(e) { raw = ''; }
raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();
let brief = {};
try { brief = JSON.parse(raw); } catch(e) { brief = { parse_error: 'Failed: ' + raw.substring(0, 200) }; }

const cueOf = (x) => x.cue || x.cue_point || x.timestamp || x.time || x.start || '';
const cueEndOf = (x) => x.cue_end || x.end || x.timestamp_end || '';
const noteOf = (x) => x.reason || x.description_note || x.note || x.purpose || '';

const fmtCued = (arr, labelKeys) => {
  if (!Array.isArray(arr)) return String(arr || '');
  return arr.map((x, i) => {
    if (typeof x === 'string') return `${i+1}. ${x}`;
    if (typeof x === 'object' && x !== null) {
      let label = '';
      for (const k of labelKeys) { if (x[k]) { label = x[k]; break; } }
      if (!label) { label = Object.entries(x).filter(([k]) => ['cue','cue_point','timestamp','time','start','cue_end','end','timestamp_end','reason','note','purpose'].indexOf(k) === -1).map(([k,v]) => `${k}: ${v}`).join(' | '); }
      const c = cueOf(x);
      const ce = cueEndOf(x);
      let range = '';
      if (c && ce) range = ` at ${c}-${ce}`;
      else if (c) range = ` at ${c}`;
      const note = noteOf(x);
      let line = `${label}${range}`;
      if (note) line += ` \u2014 ${note}`;
      return `${i+1}. ${line}`;
    }
    return `${i+1}. ${x}`;
  }).join('\n');
};

const fmtMusic = (arr) => {
  if (!Array.isArray(arr)) return String(arr || '');
  return arr.map((x, i) => {
    if (typeof x === 'string') return `${i+1}. ${x}`;
    if (typeof x === 'object' && x !== null) {
      const variant = x.variant || x.name || x.title || '';
      const part = x.part ? ` (${x.part})` : '';
      const c = cueOf(x);
      const at = c ? ` starts at ${c}` : '';
      const prompt = x.prompt || '';
      return `${i+1}. ${variant}${part}${at}\n${prompt}`;
    }
    return `${i+1}. ${String(x)}`;
  }).join('\n\n');
};

const fmtSfx = (arr) => {
  if (!Array.isArray(arr)) return String(arr || '');
  return arr.map((x, i) => {
    if (typeof x === 'string') return `${i+1}. ${x}`;
    if (typeof x === 'object' && x !== null) {
      const n = x.sound || x.name || x.effect || '';
      const c = cueOf(x);
      const dsc = noteOf(x);
      let l = n;
      if (c) l += ` at ${c}`;
      if (dsc) l += ` \u2014 ${dsc}`;
      return `${i+1}. ${l || JSON.stringify(x)}`;
    }
    return `${i+1}. ${x}`;
  }).join('\n');
};

const ct = brief.cutting_technique || {};
const ctLine = (label, v) => {
  if (typeof v === 'string') return `${label}: ${v}`;
  if (v && typeof v === 'object') {
    const c = cueOf(v);
    const t = v.technique || v.description || v.note || '';
    return `${label}${c ? ` at ${c}` : ''}: ${t}`;
  }
  return `${label}: `;
};
const cuttingText = [
  ctLine('Hook \u2192 Main', ct.hook_to_main),
  ctLine('Main \u2192 Pain', ct.main_to_pain),
  ctLine('Pain \u2192 Solution', ct.pain_to_solution),
  ctLine('Solution \u2192 CTA', ct.solution_to_cta)
].join('\n');

return { json: {
  record_id: sourceData.record_id,
  heygen_video_id: sourceData.heygen_video_id,
  screenshots_needed: fmtCued(brief.screenshots_needed, ['screenshot','description','item']),
  screenshots_needed_raw: sourceData.screenshots_needed || '',
  broll_generated: fmtCued(brief.broll_generated, ['description','broll','footage','item']),
  broll_reference: fmtCued(brief.broll_reference, ['query','search_query','reference','item']),
  hook_video_brief: brief.hook_video_brief || '',
  sound_effects: fmtSfx(brief.sound_effects),
  music_bgm: fmtMusic(brief.music_bgm),
  cutting_technique: cuttingText,
  soundbite: brief.soundbite || 'agent done for you by Alfred Ai',
  content_type: sourceData.content_type,
  platform: sourceData.platform
} };

const d = $input.item.json;
const P = [];
P.push('You are creating a production brief for a ' + d.content_type + ' video for ' + d.platform + '.');
P.push('');
P.push('TOPIC: ' + d.topic);
P.push('CATEGORY: ' + d.category);
P.push('');
P.push('FINAL SCRIPT:');
P.push(d.script);
P.push('');
P.push('TIMING RULES (mandatory - every cue must be computed from the script, never guessed):');
P.push('- Assume the voiceover is read at 150 words per minute.');
P.push('- To time any sentence: count the words that appear before it in the script, then cue = round(words_before / 150 * 60) seconds, formatted m:ss.');
P.push('- Total script duration = round(total_words / 150 * 60) seconds. No cue may exceed it.');
P.push('- Format every timestamp as m:ss, e.g. 0:07 or 1:24. Never seconds-only, never a range inside a single cue field.');
P.push('- Within each list, cues must ascend and must not repeat.');
P.push('- Every cue must land on the moment in the script the item actually supports. Anchor it to a specific sentence.');
P.push('');
P.push('Generate a complete production brief as a JSON object with these exact keys:');
P.push('');
P.push('{');
P.push('  "screenshots_needed": [list of objects, each with "screenshot" (specific description of the screenshot), "cue" (m:ss where it appears on screen), "reason" (one sentence on what point in the script it supports)],');
P.push('  "broll_generated": [list of 3-5 objects, each with "description" (the b-roll footage to source or generate), "cue" (m:ss where the clip starts), "cue_end" (m:ss where the clip ends), "reason" (one sentence on the script moment it covers)],');
P.push('  "broll_reference": [list of 3-5 objects, each with "query" (a stock-footage search query for matching visual style), "cue" (m:ss), "cue_end" (m:ss). Index-align these to broll_generated: entry N here must reference the same moment as entry N there, with the same cue and cue_end],');
P.push('  "hook_video_brief": "4-second opening hook direction, covering 0:00 to 0:04",');
P.push('  "sound_effects": [list of objects - each must use "sound" (must be exactly one of: digital_readout, whoosh, impact, riser, ding, air_hit, keyboard, mouse_click, double_click, notification, camera_shutter, digital_shutter), "cue" (m:ss), and "reason" (one sentence on why this sound fits this moment)],');
P.push('  "music_bgm": [Two objects - one for Part 1 (opening, 0-40% of video) and one for Part 2 (transition, 40-100% of video). Each object must have exactly these keys: "variant": MUST be set using the CATEGORY field provided above. Format exactly as "[CATEGORY] - Part 1 (120 BPM)" for Part 1 and "[CATEGORY] - Part 2 (140 BPM)" for Part 2. Do NOT infer the category from the script content. Use only the CATEGORY value supplied. "part": either "Part 1" or "Part 2". "cue": m:ss where that part starts - Part 1 is always 0:00, Part 2 starts at 40 percent of total script duration. "prompt": a complete ready-to-use music generation prompt following AlfredAI sonic DNA. LOCKED SONIC DNA across both parts: key of A minor; warm and dark authoritative tone, never bright or harsh; warm spectral character focused in the 1500-2000 Hz range; deep, present, grounding bass; smooth warm synth melody over rich sustained atmospheric pads; punchy four-on-the-floor kick drum with crisp hi-hats; subtle industrial/construction textures (distant metallic clinks, rhythmic mechanical pulses) blended smoothly into the beat, never overpowering; spacious midrange left clear for voiceover narration; clean professional studio mix with no distortion. TEMPO STRUCTURE: Part 1 sits at 120 BPM. Part 2 begins with a smooth intentional 2-3 second tempo ramp from 120 to 140 BPM at the transition point, then holds 140 BPM. Part 1 must build gradually toward the transition. Part 2 must build to a powerful climax near the end, then fade out gradually and smoothly over the final 1-2 seconds. Part 1 intensity rules - News: moderate intensity, establish the hook, build anticipation. Education: intellectual understated pulse, warm pads lead, clarifying feel. Product: sparse minimal arrangement, deep gentle bass, subtle UI textures, effortless automation feel. Part 2 intensity rules - News: high intensity, punchier drum transients, pronounced construction/metallic textures, forward-leaning urgent action-oriented momentum. Education: deeper grounded feel, more resonant pads, construction-industry-specific sonic texture. Product: energetic tech-forward, prominent celebratory lead synth, rhythmic integrated mechanical textures. Every prompt must begin with "Instrumental only, no vocals." and end with "Keep the tone warm and dark, not bright or harsh; keep the bass deep and present, not thin; no electric guitars, no acoustic drums, no orchestral strings or horns, no chaotic or erratic tempo changes; drums punchy but never overwhelming the voiceover."],');
P.push('  "cutting_technique": {"hook_to_main": {"cue": "m:ss", "technique": ""}, "main_to_pain": {"cue": "m:ss", "technique": ""}, "pain_to_solution": {"cue": "m:ss", "technique": ""}, "solution_to_cta": {"cue": "m:ss", "technique": ""}},');
P.push('  "soundbite": "agent done for you by Alfred Ai"');
P.push('}');
P.push('');
P.push('Be specific, practical and editor-ready. Return ONLY the JSON object - no markdown, no explanation, no code fences.');
const body = {
  model: 'gpt-4.1-mini',
  messages: [
    { role: 'system', content: 'You are a professional video editor and content strategist for AlfredAI. You produce precise, actionable production briefs for video editors. Every asset you list must carry a timestamp cue computed from the script at 150 words per minute, so the editor knows exactly where it belongs on the timeline. Always respond with valid JSON only - no markdown, no explanation, no code fences.' },
    { role: 'user', content: P.join('\n') }
  ],
  temperature: 0.6,
  max_tokens: 3000
};
return { json: { ...d, brief_body: JSON.stringify(body) } };

const brief = $('4. Parse Production Brief').first().json;
const fetched = $('6b. Fetch Existing Reel Notes').first().json || {};
const f = fetched.fields || fetched;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';

const sep = '==============================';
const STAGE_TAG = 'PRODUCTION BRIEF (WF06c)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const blockRe = new RegExp('\\n*' + sep + '\\n' + esc(STAGE_TAG) + '[\\s\\S]*?(?=(\\n' + sep + '\\n)|$)', 'g');
const notesBase = freshNotes.replace(blockRe, '').trim();

const countItems = (s) => { if (!s) return 0; const m = String(s).match(/^\d+\.\s/gm); return m ? m.length : 0; };
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');

const block = sep + '\n' + STAGE_TAG
  + '\nUpdated: ' + stamp
  + '\nStage: Complete'
  + '\nTiming basis: 150 wpm, cues computed from script'
  + '\nScreenshots: ' + countItems(brief.screenshots_needed)
  + '\nB-roll clips: ' + countItems(brief.broll_generated)
  + '\nB-roll references: ' + countItems(brief.broll_reference)
  + '\nSound effects: ' + countItems(brief.sound_effects)
  + '\nBGM parts: ' + countItems(brief.music_bgm);

const notesFinal = (notesBase ? notesBase + '\n\n' : '') + block;
return { json: { ...brief, sep: sep, stage_tag: STAGE_TAG, notes_base: notesBase, reel_notes_final: notesFinal } };

const rec = $input.item.json || {};
const f = rec.fields || rec;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';

const sep = '==============================';
const STAGE_TAG = 'PRODUCTION BRIEF (WF06c)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const blockRe = new RegExp('\\n*' + sep + '\\n' + esc(STAGE_TAG) + '[\\s\\S]*?(?=(\\n' + sep + '\\n)|$)', 'g');
const notesBase = freshNotes.replace(blockRe, '').trim();
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');

const block = sep + '\n' + STAGE_TAG
  + '\nUpdated: ' + stamp
  + '\nStage: Skipped'
  + '\nNot approved: skipped';

return { json: { record_id: rec.id || '', revert_status: 'Video Ready', reel_notes_final: (notesBase ? notesBase + '\n\n' : '') + block } };
